parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "supplier": { "type": "string", "description": "Company that issued the invoice (NOT the customer, Kildare Craft Coffee Ltd)" },
    "invoice_number": { "type": "string", "description": "Invoice number exactly as printed" },
    "invoice_date": { "type": "string", "description": "Issue date as YYYY-MM-DD" },
    "due_date": { "type": "string", "description": "Payment due date as YYYY-MM-DD" },
    "currency": { "type": "string", "description": "3-letter currency code, e.g. EUR, GBP, USD" },
    "subtotal": { "type": "number", "description": "Amount before VAT" },
    "vat": { "type": "number", "description": "VAT amount; 0 if none is shown" },
    "total": { "type": "number", "description": "Final amount due, including VAT" }
  },
  "required": ["supplier", "invoice_number", "invoice_date", "due_date", "currency", "subtotal", "vat", "total"]
}
